                    no = 1;
                }
            }
            cout << (no ? "NO\n" : "YES\n");
            continue;
        }
        int num[n];
        int no = 0;
        int tgr = 1;
        for(int j = 0;j < n;++j)
        {
            if(!vis[j])
            {
                int ind = j;
